143	      themeValue: 'light',
144	      themeRefresh: 0
145	    },
146	
147	    computed: {
148	      pageStyle() {
149	        this.themeRefresh
150	        const theme = global.theme || this.themeValue
151	        return { backgroundColor: theme === 'dark' ? '#000000' : '#F5F0E8' }
152	      },
153	      cardStyle() {
154	        this.themeRefresh
155	        const theme = global.theme || this.themeValue
156	        return {
157	          backgroundColor: theme === 'dark' ? '#1A1A1A' : '#FFFFFF',
158	          borderColor: theme === 'dark' ? '#333333' : '#D4C4A8',
159	          borderWidth: '1px',
160	          borderStyle: 'solid'
161	        }
162	      },
163	      accentStyle() {
164	        this.themeRefresh
165	        const theme = global.theme || this.themeValue
166	        return { color: theme === 'dark' ? '#4D9FEE' : '#6B4226' }
167	      },
168	      textStyle() {
169	        this.themeRefresh
170	        const theme = global.theme || this.themeValue
171	        return { color: theme === 'dark' ? '#E0E0E0' : '#3D2B1F' }
172	      },
173	      hintStyle() {
174	        this.themeRefresh
175	        const theme = global.theme || this.themeValue
176	        return { color: theme === 'dark' ? '#888888' : '#A89880' }
177	      }
178	    },
179	
180	    onInit() {
181	      this.searchQuery = global.searchQuery || ''
182	      this.activeCategory = global.searchCategory || 'all'
183	      this.activeRegion = global.searchRegion || 'all'
184	      this.loadPage(1)
185	      global.addRuntimeLog('结果页打开，搜索词: ' + global.searchQuery, 'info')
186	    },
187	
188	    onShow() {
189	      if (global.theme && global.theme !== this.themeValue) {
190	        this.themeValue = global.theme
191	        this.themeRefresh = this.themeRefresh === 0 ? 1 : 0
192	      }
193	    },
194	
195	    async loadPage(page) {
196	  if (this.loading || this.allLoaded) return
197	  this.loading = true
198	
199	  try {
200	    const result = await global.searchHistory(this.searchQuery, {
201	      category: this.activeCategory,
202	      region: this.activeRegion,
203	      page: page,
204	      pageSize: this.pageSize
205	    })
206	    
207	    var formatted = (result.results || []).map(function(item) {
208	  // 取第一个关键词作为标题
209	  var title = item.title || '未知事件'
210	  if (title.indexOf(',') !== -1) {
211	    title = title.split(',')[0].trim()
212	  } else if (title.indexOf('，') !== -1) {
213	    title = title.split('，')[0].trim()
214	  }
215	  
216	  return {
217	    id: item.id || item._id,
218	    yearDisplay: item.yearDisplay || '未知',
219	    title: title,
220	    region: item.region || '未知'
221	  }
222	})
223	    
224	    if (page === 1) {
225	      this.displayList = formatted
226	    } else {
227	      this.displayList = this.displayList.concat(formatted)
228	    }
229	    
230	    this.totalCount = result.total || 0
231	    this.currentPage = page
232	    this.loading = false
233	    
234	    if (formatted.length < this.pageSize) {
235	      this.allLoaded = true
236	    }
237	  } catch(e) {
238	    console.error('[loadPage] 错误:', e)
239	    this.loading = false
240	  }
241	},
242	
243	    gotoDetail(id) {
