225	    },
226	
227	    // 形态/安全偏移适配：状态栏高度 = 设计高 + 物理安全偏移换算的设计 px（同 index.ux）
228	    adjustForScreen() {
229	      var self = this
230	      device.getInfo({
231	        success: function(data) {
232	          var screenWidth = data.screenWidth
233	          var shape = data.screenShape
234	          var safeTopPx = 0
235	          var base = 22
236	          if (shape === 'pill-shaped') {
237	            safeTopPx = 12
238	            base = 50
239	          } else if (shape === 'circle') {
240	            safeTopPx = 10
241	            base = 26
242	          }
243	          var padTop = safeTopPx > 0 ? Math.round(safeTopPx * 300 / screenWidth) : 0
244	          self.topBarPadTop = padTop
245	          self.statusbarHeight = base + padTop
246	          self.showAppTitle = (shape === 'pill-shaped') || (shape === 'circle')
247	          self.showRectTitle = !self.showAppTitle
248	          self.screentype = shape === 'circle' ? 'circle' : shape === 'pill-shaped' ? 'pill-shaped' : 'rect'
249	          console.log('[RESULT] shape=' + shape + ' screentype=' + self.screentype + ' statusbarH=' + self.statusbarHeight)
250	          if (typeof global.addRuntimeLog === 'function') {
251	            global.addRuntimeLog('[RESULT] shape=' + shape + ' screentype=' + self.screentype, 'info')
252	          }
253	        }
254	      })
255	    },
256	
257	    // 点搜索框：开/收键盘，收起时触发搜索
258	    toggleKeyboard() {
259	      if (this.isClearing) return
260	      this.showKeyboard = !this.showKeyboard
261	      if (!this.showKeyboard) {
262	        this.finishInput()
263	      }
264	    },
265	
266	    // 点「完成」：收起键盘并立即搜索
267	    finishInput() {
268	      this.showKeyboard = false
269	      this.resetAndSearch()
270	    },
271	
272	    // 清空关键词（清空时保持键盘打开状态，可继续输入）
273	    clearSearch() {
274	      this.isClearing = true
275	      this.searchQuery = ''
276	      global.searchQuery = ''
277	      this.displayList = []
278	      this.totalCount = 0
279	      this.currentPage = 1
280	      this.allLoaded = false
281	      this.searched = false
282	      var self = this
283	      setTimeout(function() { self.isClearing = false }, 200)
284	    },
285	
286	    // @complete：键盘逐字符提交（拼音候选/英文字母/空格），追加到关键词并实时搜索（防抖）
287	    onInput(evt) {
288	      var content = evt.detail.content
289	      if (content === undefined || content === null) return
290	      this.searchQuery += content
291	      global.searchQuery = this.searchQuery
292	      this.scheduleSearch()
293	    },
294	
295	    // @delete：键盘内部缓冲已空时，删除页面关键词末字符
296	    onDelete() {
297	      this.searchQuery = this.searchQuery.slice(0, -1)
298	      global.searchQuery = this.searchQuery
299	      this.scheduleSearch()
300	    },
301	
302	    // 防抖实时搜索（避免逐键触发）
303	    scheduleSearch() {
304	      var self = this
305	      if (this.searchTimer) clearTimeout(this.searchTimer)
306	      this.searchTimer = setTimeout(function() {
307	        self.resetAndSearch()
308	      }, 400)
309	    },
310	
311	    // 重置分页并搜索第 1 页
312	    resetAndSearch() {
313	      if (!this.searchQuery || !this.searchQuery.trim()) {
314	        this.displayList = []
315	        this.totalCount = 0
316	        this.currentPage = 1
317	        this.allLoaded = false
318	        this.searched = false
319	        return
320	      }
321	      this.currentPage = 1
322	      this.allLoaded = false
323	      this.searched = true
324	      this.loadPage(1)
325	    },
326	
327	    async loadPage(page) {
328	      if (this.loading || this.allLoaded) return
329	      if (!this.searchQuery || !this.searchQuery.trim()) return
330	      this.loading = true
331	      try {
332	        var result = await global.searchHistory(this.searchQuery, {
333	          category: this.activeCategory,
334	          region: this.activeRegion,
335	          page: page,
336	          pageSize: this.pageSize
337	        })
338	        var formatted = (result.results || []).map(function(item) {
339	          // 取第一个关键词作为标题
340	          var title = item.title || '未知事件'
341	          if (title.indexOf(',') !== -1) {
342	            title = title.split(',')[0].trim()
343	          } else if (title.indexOf('，') !== -1) {
344	            title = title.split('，')[0].trim()
345	          }
346	          return {
347	            id: item.id || item._id,
348	            yearDisplay: item.yearDisplay || '未知',
349	            title: title,
350	            region: item.region || '未知'
351	          }
352	        })
353	        if (page === 1) {
354	          this.displayList = formatted
355	        } else {
356	          this.displayList = this.displayList.concat(formatted)
357	        }
358	        this.totalCount = result.total || 0
359	        this.currentPage = page
360	        this.loading = false
361	        if (formatted.length < this.pageSize) {
362	          this.allLoaded = true
363	        }
364	      } catch (e) {
365	        console.error('[loadPage] 错误:', e)
366	        this.loading = false
367	      }
368	    },
369	
370	    // 滚动到底自动加载下一页（键盘弹出时不触发）
371	    onScrollBottom() {
372	      if (this.showKeyboard) return
373	      if (this.loading || this.allLoaded) return
374	      if (!this.displayList.length) return
375	      this.loadPage(this.currentPage + 1)
376	    },
377	
378	    gotoDetail(id) {
379	      if (this.showKeyboard) return
380	      if (this.$app.$def.isNavigating) return
381	      if (typeof global.addRuntimeLog === 'function') {
382	        global.addRuntimeLog('从结果页打开详情: ID=' + id, 'info')
383	      }
384	      global.selectedEventId = id
385	      router.push({ uri: '/pages/detail' })
386	    },
387	
388	    // 右滑返回；键盘弹出时先收起键盘
389	    onSwipe(eve) {
390	      if (eve.direction === 'right') {
391	        if (this.showKeyboard) {
392	          this.finishInput()
393	          return
394	        }
395	        if (this.$app.$def.isNavigating) return
396	        router.back()
397	      }
398	    }
399	  }
400	</script>
