152	<script>
153	  import router from '@system.router'
154	  import device from '@system.device'
155	
156	  // 手写补零（避免 padStart 的轻量运行时兼容风险）
157	  function pad2(n) {
158	    return n < 10 ? '0' + n : '' + n
159	  }
160	
161	  export default {
162	    private: {
163	      time: '00:00',
164	      timeTimer: null,
165	      statusbarHeight: 22,
166	      topBarPadTop: 0,
167	      showAppTitle: false,
168	      showRectTitle: true,
169	      screentype: 'rect',
170	      screenAdjusted: false,
171	      showKeyboard: false,
172	      searchQuery: '',
173	      displayList: [],
174	      totalCount: 0,
175	      currentPage: 1,
176	      pageSize: 20,
177	      loading: false,
178	      allLoaded: false,
179	      searched: false,
180	      activeCategory: 'all',
181	      activeRegion: 'all',
182	      searchTimer: null,
183	      isClearing: false
184	    },
185	
186	    computed: {
187	      // 键盘打开时追加光标
188	      displayQuery() {
189	        return this.searchQuery + (this.showKeyboard ? '▏' : '')
190	      }
191	    },
192	
193	    onInit() {
194	      this.searchQuery = global.searchQuery || ''
195	      this.activeCategory = global.searchCategory || 'all'
196	      this.activeRegion = global.searchRegion || 'all'
197	      this.updateTime()
198	      this.timeTimer = setInterval(() => { this.updateTime() }, 30000)
199	      // 有词直接加载；无词弹出键盘等待输入
200	      if (this.searchQuery && this.searchQuery.trim()) {
201	        this.searched = true
202	        this.loadPage(1)
203	      } else {
204	        this.showKeyboard = true
205	      }
206	      if (typeof global.addRuntimeLog === 'function') {
207	        global.addRuntimeLog('结果页打开，搜索词: ' + global.searchQuery, 'info')
208	      }
209	    },
210	
211	    // onShow 时 DOM 已 ready，获取屏幕信息做形态/安全偏移适配（仅执行一次）
212	    onShow() {
213	      if (this.screenAdjusted) return
214	      this.screenAdjusted = true
215	      this.adjustForScreen()
216	    },
217	
218	    onDestroy() {
219	      if (this.timeTimer) clearInterval(this.timeTimer)
220	      if (this.searchTimer) clearTimeout(this.searchTimer)
221	    },
222	
223	    updateTime() {
224	      var now = new Date()
225	      this.time = pad2(now.getHours()) + ':' + pad2(now.getMinutes())
226	    },
227	
228	    // 形态/安全偏移适配：状态栏高度 = 设计高 + 物理安全偏移换算的设计 px（同 index.ux）
229	    adjustForScreen() {
230	      var self = this
231	      device.getInfo({
232	        success: function(data) {
233	          var screenWidth = data.screenWidth
234	          var shape = data.screenShape
235	          var safeTopPx = 0
236	          var base = 22
237	          if (shape === 'pill-shaped') {
238	            safeTopPx = 12
239	            base = 50
240	          } else if (shape === 'circle') {
241	            safeTopPx = 10
242	            base = 26
243	          }
244	          var padTop = safeTopPx > 0 ? Math.round(safeTopPx * 300 / screenWidth) : 0
245	          self.topBarPadTop = padTop
246	          self.statusbarHeight = base + padTop
247	          self.showAppTitle = (shape === 'pill-shaped') || (shape === 'circle')
248	          self.showRectTitle = !self.showAppTitle
249	          self.screentype = shape === 'circle' ? 'circle' : shape === 'pill-shaped' ? 'pill-shaped' : 'rect'
250	          console.log('[RESULT] shape=' + shape + ' screentype=' + self.screentype + ' statusbarH=' + self.statusbarHeight)
251	          if (typeof global.addRuntimeLog === 'function') {
252	            global.addRuntimeLog('[RESULT] shape=' + shape + ' screentype=' + self.screentype, 'info')
253	          }
254	        }
255	      })
256	    },
257	
258	    // 点搜索框：开/收键盘，收起时触发搜索
259	    toggleKeyboard() {
260	      if (this.isClearing) return
261	      this.showKeyboard = !this.showKeyboard
262	      if (!this.showKeyboard) {
263	        this.finishInput()
264	      }
265	    },
266	
267	    // 点「完成」：收起键盘并立即搜索
268	    finishInput() {
269	      this.showKeyboard = false
270	      this.resetAndSearch()
271	    },
272	
273	    // 清空关键词（清空时保持键盘打开状态，可继续输入）
274	    clearSearch() {
275	      this.isClearing = true
276	      this.searchQuery = ''
277	      global.searchQuery = ''
278	      this.displayList = []
279	      this.totalCount = 0
280	      this.currentPage = 1
281	      this.allLoaded = false
282	      this.searched = false
283	      var self = this
284	      setTimeout(function() { self.isClearing = false }, 200)
285	    },
286	
287	    // @complete：键盘逐字符提交（拼音候选/英文字母/空格），追加到关键词并实时搜索（防抖）
288	    onInput(evt) {
289	      var content = evt.detail.content
290	      if (content === undefined || content === null) return
291	      this.searchQuery += content
292	      global.searchQuery = this.searchQuery
293	      this.scheduleSearch()
294	    },
295	
296	    // @delete：键盘内部缓冲已空时，删除页面关键词末字符
297	    onDelete() {
298	      this.searchQuery = this.searchQuery.slice(0, -1)
299	      global.searchQuery = this.searchQuery
300	      this.scheduleSearch()
301	    },
302	
303	    // 防抖实时搜索（避免逐键触发）
304	    scheduleSearch() {
305	      var self = this
306	      if (this.searchTimer) clearTimeout(this.searchTimer)
307	      this.searchTimer = setTimeout(function() {
308	        self.resetAndSearch()
309	      }, 400)
310	    },
311	
312	    // 重置分页并搜索第 1 页
313	    resetAndSearch() {
314	      if (!this.searchQuery || !this.searchQuery.trim()) {
315	        this.displayList = []
316	        this.totalCount = 0
317	        this.currentPage = 1
318	        this.allLoaded = false
319	        this.searched = false
320	        return
321	      }
322	      this.currentPage = 1
323	      this.allLoaded = false
324	      this.searched = true
325	      this.loadPage(1)
326	    },
327	
328	    async loadPage(page) {
329	      if (this.loading || this.allLoaded) return
330	      if (!this.searchQuery || !this.searchQuery.trim()) return
331	      this.loading = true
332	      try {
333	        var result = await global.searchHistory(this.searchQuery, {
334	          category: this.activeCategory,
335	          region: this.activeRegion,
336	          page: page,
337	          pageSize: this.pageSize
338	        })
339	        var formatted = (result.results || []).map(function(item) {
340	          // 取第一个关键词作为标题
341	          var title = item.title || '未知事件'
342	          if (title.indexOf(',') !== -1) {
343	            title = title.split(',')[0].trim()
344	          } else if (title.indexOf('，') !== -1) {
345	            title = title.split('，')[0].trim()
346	          }
347	          return {
348	            id: item.id || item._id,
349	            yearDisplay: item.yearDisplay || '未知',
350	            title: title,
351	            region: item.region || '未知'
352	          }
353	        })
354	        if (page === 1) {
355	          this.displayList = formatted
356	        } else {
357	          this.displayList = this.displayList.concat(formatted)
358	        }
359	        this.totalCount = result.total || 0
360	        this.currentPage = page
361	        this.loading = false
362	        if (formatted.length < this.pageSize) {
363	          this.allLoaded = true
364	        }
365	      } catch (e) {
366	        console.error('[loadPage] 错误:', e)
367	        this.loading = false
368	      }
369	    },
370	
371	    // 滚动到底自动加载下一页（键盘弹出时不触发）
372	    onScrollBottom() {
373	      if (this.showKeyboard) return
374	      if (this.loading || this.allLoaded) return
375	      if (!this.displayList.length) return
376	      this.loadPage(this.currentPage + 1)
377	    },
378	
379	    gotoDetail(id) {
380	      if (this.showKeyboard) return
381	      if (this.$app.$def.isNavigating) return
382	      if (typeof global.addRuntimeLog === 'function') {
383	        global.addRuntimeLog('从结果页打开详情: ID=' + id, 'info')
384	      }
385	      global.selectedEventId = id
386	      router.push({ uri: '/pages/detail' })
387	    },
388	
389	    // 右滑返回；键盘弹出时先收起键盘
390	    onSwipe(eve) {
391	      if (eve.direction === 'right') {
392	        if (this.showKeyboard) {
393	          this.finishInput()
394	          return
395	        }
396	        if (this.$app.$def.isNavigating) return
397	        router.back()
398	      }
399	    }
400	  }
401	</script>
